  "ID"         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ID_Akce"    INTEGER
);

-- Krok 2: Vložení řídicího řádku
INSERT INTO "Filtr" ("ID", "ID_Akce") VALUES (1, NULL);
